M.ByCategory = {}
M.BySlot = {}
for _, item in ipairs(M.Items) do
    local cat = item.category
    M.ByCategory[cat] = M.ByCategory[cat] or {}
    table.insert(M.ByCategory[cat], item)
    local slot = M.Categories[cat] and M.Categories[cat].slot or "?"
    M.BySlot[slot] = M.BySlot[slot] or {}
    table.insert(M.BySlot[slot], item)
end

---@param slot string 槽位：外攻武器/内攻武器/副手/头部/胸甲/手部/足部/腰部/项链/戒指
function M.GetBySlot(slot)
    return M.BySlot[slot] or {}
end

return M
